 b=next(b for b in L.read('batches') if b['batch_id']=='B0014');pubs={p['registry_key']:p for p in L.read('publication_reviews')}
 action='Tenof25 inputs screened; protein-crystallization seeds, chiral sensor and cell-spreading triangle sources inspected with unresolved label/scaffold conflicts.'
